            codes.Add("es", Code_es());
            codes.Add("fr", Code_fr());
            codes.Add("pt", Code_pt());
            codes.Add("ptbr", Code_ptbr());
            codes.Add("ru", Code_ru());
            codes.Add("ro", Code_ro());
            codes.Add("id", Code_id());
            codes.Add("bhs", Code_bhs());
            codes.Add("cs", Code_cs());
            sentences.Add("es", Sentences_es());
            sentences.Add("fr", Sentences_fr());
            sentences.Add("pt", Sentences_pt());
            sentences.Add("ptbr", Sentences_ptbr());
            sentences.Add("ru", Sentences_ru());
            sentences.Add("ro", Sentences_ro());
            sentences.Add("id", Sentences_id());
            sentences.Add("bhs", Sentences_bhs());
            sentences.Add("cs", Sentences_cs());
        }

